// Normalizes a Belgian VAT or enterprise number.
// Accepts: BE0203.201.340 / 0203201340 / 203 201 340 / BE 0203201340
const raw = String($json['Belgian VAT or enterprise number'] ?? '').trim();

let digits = raw.replace(/[^0-9]/g, '');

// Old nine-digit numbers get a leading zero
if (digits.length === 9) digits = '0' + digits;

const structureValid = digits.length === 10 && (digits[0] === '0' || digits[0] === '1');

// Mod 97 check: the last two digits are the check number
let checksumOk = false;
if (structureValid) {
  const base = parseInt(digits.slice(0, 8), 10);
  const check = parseInt(digits.slice(8, 10), 10);
  checksumOk = (97 - (base % 97)) === check;
}

return [{
  json: {
    entered: raw,
    number: digits,
    vatNumber: 'BE' + digits,
    formatted: digits ? `BE ${digits.slice(0,4)}.${digits.slice(4,7)}.${digits.slice(7,10)}` : '',
    structureValid,
    checksumOk,
    email: $json['Email for the report'] || ''
  }
}];

// Combines the three sources into one readable report.
const base    = $('Normalize VAT Number').first().json;
const vies    = $('Fetch VIES VAT Status').first().json ?? {};
const kbo     = $('Get Peppol by KBO Number').first().json ?? {};
const vatPep  = $('Get Peppol by VAT Number').first().json ?? {};

const hits = (o) => Number(o['total-result-count'] ?? 0);
const peppolKbo = hits(kbo);
const peppolVat = hits(vatPep);
const peppolActive = peppolKbo > 0 || peppolVat > 0;

// Fall back to the Peppol entry for the name if VIES returned nothing
const match = (kbo.matches && kbo.matches[0]) || (vatPep.matches && vatPep.matches[0]) || null;
const peppolName = match?.entities?.[0]?.name?.[0]?.name ?? null;

const vatValid = vies.valid === true;
const name = (vies.name && vies.name !== '---') ? vies.name : peppolName;
const address = (vies.address && vies.address !== '---') ? String(vies.address).replace(/\n/g, ', ') : null;

let verdict;
if (!base.structureValid || !base.checksumOk) {
  verdict = 'This is not a valid Belgian enterprise number. Check that you have all ten digits.';
} else if (!vatValid) {
  verdict = 'The number is structurally correct but is not listed as an active VAT number in VIES. The business may have ceased trading, may not be VAT liable, or VIES was temporarily unreachable.';
} else if (!peppolActive) {
  verdict = 'Valid VAT number, but this company is not in the Peppol network. Your e-invoice will not arrive: ask them to register for Peppol, or send a PDF invoice for now.';
} else {
  verdict = 'All clear. The VAT number is valid and this company can receive e-invoices over Peppol.';
}

return [{
  json: {
    entered: base.entered,
    number: base.formatted,
    structureValid: base.structureValid && base.checksumOk,
    vatValid,
    name: name ?? 'not found',
    address: address ?? 'not found',
    peppolActive,
    peppolFoundVia: peppolKbo > 0 ? 'enterprise number (0208)' : (peppolVat > 0 ? 'VAT number (9925)' : 'not found'),
    readyForEInvoicing: vatValid && peppolActive,
    verdict,
    checkedOn: new Date().toISOString().slice(0, 10)
  }
}];

